func adminWarehouseBranchLabel(branchID *int64, branches []*org.Branch, lang string) string {
	if branchID == nil || *branchID <= 0 {
		return i18n.T(lang, "vendor_warehouses.general_warehouse")
	}
	for _, b := range branches {
		if b != nil && b.ID == *branchID {
			if name := b.Name.Get(i18n.Lang(lang)); name != "" {
				return name
			}
		}
	}
	return fmt.Sprintf("#%d", *branchID)
}

func boolParam(v bool) string {
	if v {
		return "1"
	}
	return "0"
}

